// Generic Text/4 byte transport, DOM and explicit local file ownership.
// The fixture computes text transformations, never product mathematics/cases.
import assert from 'node:assert/strict';
import {readFileSync,existsSync,mkdtempSync,mkdirSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {createServer} from 'node:http';
import {createRequire} from 'node:module';
import test,{before,after} from 'node:test';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const path='crates/prismpm/src/research_workbench/runtime.js';
// Before implementation the actual current owner supplies the intended RED.
const template=read(existsSync(new URL('../'+path,import.meta.url))?path:'crates/prismpm/src/workbench/runtime.js');
const fixture=JSON.parse(read('tests/data/research-workbench-model-document.json')).application;
const require=createRequire('/opt/prismpm/oracles/package.json');const {chromium,firefox}=require('playwright');
const executablePath=process.arch==='arm64'?'/ms-playwright/chromium_headless_shell-cft-157.0.8099.0/chrome-headless-shell-linux-arm64/chrome-headless-shell':'/ms-playwright/chromium_headless_shell-cft-157.0.8099.0/chrome-headless-shell-linux64/chrome-headless-shell';
const MODEL='a'.repeat(64),US='\u001f';let browser;
before(async()=>{assert.equal(require('playwright/package.json').version,'1.62.1');browser=await chromium.launch({headless:true,executablePath});assert.equal(browser.version(),'157.0.8099.0');});
after(async()=>{await browser?.close();});
const clone=x=>JSON.parse(JSON.stringify(x));
function answer(value='HELLO',action='compute') {return {version:2,status:'ok',operation:'echo',message:'Computed by the actual fixture binding.',rows:1,columns:1,cells:[value],details:[],request:value.toLowerCase(),response:value,error:'',action,selection:{row:0,column:0},tables:[],panels:[],comparison:{status:'none',message:''},exchange:{status:'none',file_name:'',file_text:'',draft:null}};}
function source(view=fixture.view,body=template,outputLimit=fixture.response_maximum) {return body.replaceAll('__INPUT_LIMIT__',String(fixture.request_maximum)).replaceAll('__OUTPUT_LIMIT__',String(outputLimit)).replaceAll('__BINDING__','"./binding.js"').replaceAll('__TRANSPORT__','"browser"').replaceAll('__MODEL_ID__',JSON.stringify(MODEL)).replace('__VIEW__',JSON.stringify(view));}
function binding(model=MODEL) {return `const model=${JSON.stringify(model)};export function model_id(){return model;}export default async function(options){if(!(options.module_or_path instanceof Response))throw new Error('explicit response');await WebAssembly.instantiateStreaming(options.module_or_path);}export function invoke_bytes(bytes){const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes),i=text.indexOf('\\u001f'),prefix=text.slice(0,i),raw=text.slice(i+1);let e;try{e=JSON.parse(raw);}catch{e={values:[raw],controls:[],operation:'echo',row:0,column:0,model_id:model,case_text:''};}const action=(prefix==='compute-v4'||prefix==='ui-raw-v1')?'compute':prefix.replace('action-','');const value=(e.values[0]||e.controls[0]||'hello').toUpperCase();if(value==='SLOW'){const stop=performance.now()+1000;while(performance.now()<stop){}}const r=(${answer.toString()})(value,action);r.operation=e.operation;r.selection={row:e.row,column:e.column};if(action==='trace'||action==='tool'||action==='inspect')r.tables=[{id:'trace',title:'Exact source rows',columns:['Index','Value'],rows:[['0',value],['1',value+'1'],['2',value+'2']]}];if(action==='compare'){r.panels=[{id:'first',title:'First actual route',rows:1,columns:1,cells:[value],request:'first:'+value,response:value},{id:'second',title:'Second actual route',rows:1,columns:1,cells:[value],request:'second:'+value,response:value}];r.comparison={status:'equivalent',message:'Both fixture routes returned identical exact text.'};}if(action==='export'){r.exchange={status:'exported',file_name:'fixture-case.json',file_text:JSON.stringify({model_id:e.model_id,operation:e.operation,value,controls:e.controls}),draft:null};}if(action==='import'||action==='recompute'){const c=JSON.parse(e.case_text);r.exchange={status:action==='import'&&c.model_id!==e.model_id?'identity-mismatch':'imported',file_name:'',file_text:'',draft:{operation:c.operation||'echo',values:c.operation==='inspect-tool'?[]:[c.value.toLowerCase()],raw:c.value.toLowerCase(),controls:c.controls||[],row:0,column:0}};r.operation=r.exchange.draft.operation;if(r.exchange.status==='identity-mismatch'){r.rows=r.columns=0;r.cells=[];r.request=r.response='';}else{r.cells=[c.value.toUpperCase()];r.request=c.value.toLowerCase();r.response=c.value.toUpperCase();r.comparison={status:'equivalent',message:'Source recomputed the observation.'};}}if(!raw.startsWith('{')){r.version=1;for(const k of ['action','selection','tables','panels','comparison','exchange'])delete r[k];}return new TextEncoder().encode(JSON.stringify(r));}`;}
async function withPage(run,{body=template,view=clone(fixture.view),model=MODEL,bindingSource=null,engineBrowser=browser}={}){const requests=[],calls=[];const wasm=Buffer.from('0061736d01000000','hex');const server=createServer(async(req,res)=>{requests.push(req.url);const pathname=new URL(req.url,'http://localhost').pathname;res.setHeader('cache-control','no-store');if(pathname==='/app.js'){res.setHeader('content-type','text/javascript');res.end(source(view,body));}else if(pathname==='/binding.js'){res.setHeader('content-type','text/javascript');res.end(bindingSource??binding(model));}else if(pathname==='/binding_bg.wasm'){res.setHeader('content-type','application/wasm');res.end(wasm);}else if(pathname==='/'){res.setHeader('content-type','text/html');res.end('<!doctype html><html lang="en"><title>Generic research fixture</title><body><script type="module" src="/app.js"></script></body></html>');}else{res.statusCode=404;res.end();}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const context=await engineBrowser.newContext(),page=await context.newPage();page.setDefaultTimeout(2000);const errors=[];page.on('pageerror',e=>errors.push(e.message));await context.addInitScript(()=>{window.__researchCalls=[];const Native=window.Worker;window.Worker=class extends Native{postMessage(data,options){if(data?.type==='invoke')window.__researchCalls.push(new TextDecoder('utf-8',{fatal:true}).decode(data.input));return super.postMessage(data,options);}};});try{await page.goto('http://127.0.0.1:'+server.address().port);await run({page,context,requests,calls});assert.deepEqual(errors,[]);}finally{await context.close();await new Promise(r=>server.close(r));}}
async function compute(page){await page.locator('#guided-submit').waitFor({state:'visible'});await page.waitForFunction(()=>!document.querySelector('#guided-submit').disabled);await page.locator('#guided-submit').click();await page.waitForFunction(()=>document.querySelector('#status').dataset.state==='ready');assert.equal(await page.locator('#result').textContent(),'HELLO');}
