test('research_workbench_model_keyed_modules_ignore_previous_deployment_http_cache',async()=>{
 const oldCss=read('crates/prismpm/src/workbench/style.css'),currentCss=read('crates/prismpm/src/research_workbench/style.css');assert.notEqual(oldCss,currentCss);
 const key='?model_id='+MODEL,oldApp="throw new Error('previous deployment shell');",oldBinding=binding().replace('export function model_id(){return model;}','');assert.notEqual(oldBinding,binding());
 async function check(body=template,expected='ready',keyStylesheet=true){
  let phase='old';const requests=[];const wasm=Buffer.from('0061736d01000000','hex');
  const server=createServer((req,res)=>{const url=new URL(req.url,'http://localhost'),pathname=url.pathname;let bytes,type='text/javascript';requests.push({url:req.url,phase});res.setHeader('cache-control','public, max-age=600');if(pathname==='/warm'){type='text/html';bytes='<title>Generic cache fixture</title>';}else if(pathname==='/'){type='text/html';res.setHeader('cache-control','no-store');bytes='<html lang="en"><title>Current fixture</title><link rel="stylesheet" href="/app.css'+(keyStylesheet?key:'')+'"><script type="module" src="/app.js'+key+'"></script></html>';}else if(pathname==='/app.js')bytes=phase==='old'?oldApp:source(fixture.view,body);else if(pathname==='/app.css'){type='text/css';bytes=phase==='old'?oldCss:currentCss;}else if(pathname==='/binding.js')bytes=phase==='old'?oldBinding:binding();else if(pathname==='/binding_bg.wasm'){type='application/wasm';bytes=wasm;}else{res.writeHead(404);res.end();return;}res.setHeader('content-type',type);res.end(bytes);});await new Promise(r=>server.listen(0,'127.0.0.1',r));
  const context=await browser.newContext(),page=await context.newPage(),workerUrls=[];page.on('worker',worker=>workerUrls.push(worker.url()));
  try{const origin='http://127.0.0.1:'+server.address().port;await page.goto(origin+'/warm');await page.evaluate(async()=>{for(const name of ['/app.js','/binding.js','/app.css'])await(await fetch(name,{cache:'force-cache'})).text();});const warmed=requests.length;await page.evaluate(async()=>{for(const name of ['/app.js','/binding.js','/app.css'])await(await fetch(name,{cache:'force-cache'})).text();});assert.equal(requests.length,warmed,'old module bytes are genuinely cached before current deployment');phase='current';await page.goto(origin+'/');await page.waitForFunction(()=>['ready','load_error'].includes(document.querySelector('#status')?.dataset.state));assert.equal(await page.locator('#status').getAttribute('data-state'),expected,'current source model must acquire coherent modules rather than cached previous-deployment glue');const current=requests.filter(row=>row.phase==='current');assert(current.some(row=>row.url==='/app.js'+key));assert(workerUrls.every(url=>url===origin+'/app.js'+key));if(expected==='ready'){assert.equal(current.filter(row=>row.url==='/app.css'+key).length,1,'current-model stylesheet request must bypass previous cache');assert.equal(current.filter(row=>row.url==='/app.css').length,0);assert.equal(await page.locator('#case-content').evaluate(node=>getComputedStyle(node).minHeight),'160px');assert.equal(current.filter(row=>row.url==='/binding.js'+key).length,1);assert.equal(current.filter(row=>row.url==='/binding.js').length,0);assert.equal(current.filter(row=>row.url==='/binding_bg.wasm').length,1);await compute(page);}else assert.equal(await page.locator('#guided-submit').isDisabled(),true);}
  finally{await context.close();await new Promise(r=>server.close(r));}
 }
 await check();
 await assert.rejects(check(template,'ready',false),error=>error.code==='ERR_ASSERTION'&&error.message.includes('current-model stylesheet request must bypass previous cache'));
 const marker="bindingUrl.searchParams.set('model_id',MODEL_ID);";assert.equal(template.split(marker).length,2);await check(template.replace(marker,''),'load_error');
});

