test('research_workbench_imported_draft_preserves_exact_source_text_until_explicit_edit',async()=>{
 const view=clone(fixture.view),op=view.operations[0];
 const other={...clone(op.fields[0]),id:'other',label:'Other exact source text',kind:'text',initial_value:'side'};
 op.fields.push(other);for(const example of op.examples)example.values.push('side');
 op.inspection.fields=[{...clone(view.research.tools[0].action.fields[0]),kind:'multiline'}];
 const second=clone(op);second.id='other-echo';second.label='Other operation';second.request_prefix='compute-other-v4';second.fields[0].initial_value='new operation';for(const example of second.examples)example.values=['new operation','new side'];view.operations.push(second);
 const code=`export function model_id(){return ${JSON.stringify(MODEL)};}export default async function(options){await WebAssembly.instantiateStreaming(options.module_or_path);}export function invoke_bytes(bytes){const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes),split=text.indexOf(${JSON.stringify(US)}),prefix=text.slice(0,split),e=JSON.parse(text.slice(split+1)),action=prefix==='compute-v4'||prefix==='ui-raw-v1'?'compute':prefix.replace('action-',''),r=${JSON.stringify(answer('VALID'))};r.operation=e.operation;r.action=action;r.selection={row:e.row,column:e.column};r.request=e.request;if(action==='export')r.exchange={status:'exported',file_name:'fixture-case.json',file_text:JSON.stringify({operation:e.operation,values:e.values,raw:e.request,controls:e.controls}),draft:null};if(action==='import'||action==='recompute'){const c=JSON.parse(e.case_text);r.exchange={status:action==='import'&&c.model_id!==e.model_id?'identity-mismatch':'imported',file_name:'',file_text:'',draft:c.draft};r.operation=c.draft.operation;r.request=c.draft.raw;if(r.exchange.status==='identity-mismatch'){r.rows=r.columns=0;r.cells=[];r.request=r.response='';}else r.comparison={status:'equivalent',message:'The source fixture recomputed exact text.'};}return new TextEncoder().encode(JSON.stringify(r));}`;
 const guided={operation:'echo',values:['alpha\r\nbeta','left\rright'],raw:'opaque\r\nwire',controls:['setting\rvalue'],row:0,column:0};
 const tool={operation:'inspect-tool',values:[],raw:'tool\r\nwire',controls:['tool\rcontrol'],row:0,column:0};
 const raw={operation:'raw',values:[],raw:'raw\r\nrequest\rtail',controls:['raw\r\nsetting'],row:0,column:0};
 // The fixture owns the returned draft; browser code must transport these
 // opaque strings rather than infer a product case format or normalize them.
 const importDraft=async(page,draft,foreign=false)=>{await page.locator('#case-file').setInputFiles({name:'source-case.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify({model_id:foreign?'b'.repeat(64):MODEL,draft}))});await page.locator('#case-import').click();await page.waitForFunction(want=>document.querySelector('#case-status').dataset.state===want,foreign?'identity-mismatch':'imported');};
 const exportDraft=async page=>{const before=await page.evaluate(()=>window.__researchCalls.length);await page.locator('#case-export').click();await page.waitForFunction(before=>window.__researchCalls.length===before+1,before);await page.waitForFunction(()=>!document.querySelector('#case-download').disabled);const call=await page.evaluate(()=>window.__researchCalls.at(-1)),envelope=JSON.parse(call.slice(call.indexOf(US)+1));const file=JSON.parse(await page.locator('#case-content').inputValue());return {envelope,file};};
 const inputOnly=async(page,selector,event='input')=>page.locator(selector).evaluate((node,event)=>node.dispatchEvent(new Event(event,{bubbles:true})),event);
 const scenarios={
  guided:async page=>{await importDraft(page,guided);let current=await exportDraft(page);assert.deepEqual(current.file.values,guided.values,'untouched multiline and single-line source fields must retain CRLF/CR');assert.deepEqual(current.file.controls,guided.controls);await inputOnly(page,'#field-message');current=await exportDraft(page);assert.deepEqual(current.file.values,[guided.values[0].replaceAll('\r\n','\n').replaceAll('\r','\n'),guided.values[1]],'same-value input retires only that field');assert.deepEqual(current.file.controls,guided.controls);await inputOnly(page,'#field-other','change');current=await exportDraft(page);assert.equal(current.file.values[1],'leftright','same-value change retires a single-line field');assert.deepEqual(current.file.controls,guided.controls);await importDraft(page,guided,true);await page.locator('#case-recompute').click();await page.waitForFunction(()=>document.querySelector('#case-status').dataset.state==='imported');current=await exportDraft(page);assert.deepEqual(current.file.values,guided.values,'explicit recomputation restores fresh exact source text');await page.locator('#example').selectOption('hello');await page.locator('#load-example').click();current=await exportDraft(page);assert.deepEqual(current.file.values,['hello','side']);await importDraft(page,guided);await page.locator('#reset').click();current=await exportDraft(page);assert.deepEqual(current.file.values,['hello','side']);await importDraft(page,guided);await page.locator('#operation').selectOption(second.id);current=await exportDraft(page);assert.deepEqual(current.file.values,['new operation','new side']);},
  tool:async page=>{await importDraft(page,tool);let current=await exportDraft(page);assert.equal(current.file.operation,tool.operation);assert.deepEqual(current.file.controls,tool.controls,'untouched single-line source tool controls must retain CR');await inputOnly(page,'#tool-field-detail','change');current=await exportDraft(page);assert.deepEqual(current.file.controls,['toolcontrol'],'a deliberate same-value tool change retires its original');},
  raw:async page=>{await importDraft(page,raw);let current=await exportDraft(page);assert.equal(current.file.operation,'raw');assert.equal(current.file.raw,raw.raw,'untouched raw source bytes must retain CRLF and lone CR');assert.deepEqual(current.file.controls,raw.controls);await inputOnly(page,'#request');current=await exportDraft(page);assert.equal(current.file.raw,raw.raw.replaceAll('\r\n','\n').replaceAll('\r','\n'));assert.deepEqual(current.file.controls,raw.controls,'raw editing preserves an untouched inspector control');await inputOnly(page,'#research-inspection-field-detail','change');current=await exportDraft(page);assert.deepEqual(current.file.controls,[raw.controls[0].replaceAll('\r\n','\n').replaceAll('\r','\n')]);}
 };
 const failures=[];for(const [name,run]of Object.entries(scenarios)){try{await withPage(async({page})=>{await page.waitForFunction(()=>!document.querySelector('#guided-submit').disabled);await run(page);},{view,bindingSource:code});}catch(error){failures.push({name,message:error.message});}}
 console.log('EXACT_DRAFT_FIDELITY '+JSON.stringify(failures));assert.deepEqual(failures,[],'every untouched imported source string must survive browser control normalization');
 const marker='const editSourceText=node=>retainedSource.delete(node);';assert.equal(template.split(marker).length,2,'the mutation binds the actual single-node edit owner');
 for(const replacement of ['const editSourceText=node=>{};','const editSourceText=node=>{retainedSource=new WeakMap();};']){await assert.rejects(()=>withPage(async({page})=>{await page.waitForFunction(()=>!document.querySelector('#guided-submit').disabled);await scenarios.guided(page);},{view,bindingSource:code,body:template.replace(marker,replacement)}),error=>error.code==='ERR_ASSERTION','retaining edited text or discarding every other field must be observable');}
});


